-- Posterhangers in plaats van lijsten. Opgezocht op 29 oktober 2026 in de live-API van Prodigi (alleen
-- productgegevens en offertes; er is niets besteld) en beoordeeld met beoordeelProduct() uit api/_prodigi.js.
--
--   30 × 40 cm   POSTER-HANGER-30-12X16-PORT   hanger 32 cm breed   kostprijs NL € 21,60 excl. btw (incl. verzending)
--   50 × 70 cm   POSTER-HANGER-50-20X28-PORT   hanger 52 cm breed   kostprijs NL € 28,60
--   70 × 100 cm  POSTER-HANGER-80-28X40-PORT   hanger 86 cm breed   kostprijs NL € 44,60 (breder dan de poster: 71 cm)
--   kleuren      zwart (black), naturel (natural), wit (white): zelfde prijs bij Prodigi
--   print        dezelfde EMA-print van 200 g/m² als de losse poster (zelfde pixeleis), dus hetzelfde drukbestand
--
-- Een variant met ophanging heeft lijst = 'hanger' en lijst_kleur = de Prodigi-kleur. Hij krijgt geen eigen
-- drukbestand: de catalogus gebruikt dat van dezelfde poster zonder hanger (api/_catalogus.js).
-- Verkoopprijzen (incl. btw) zijn een voorstel: € 45 / € 65 / € 99. Aan te passen in /admin → producten.

alter table public.varianten drop constraint if exists varianten_ophanging_check;
alter table public.varianten add constraint varianten_ophanging_check check (
  (lijst is null and lijst_kleur is null) or (lijst = 'hanger' and lijst_kleur in ('black','natural','white')));

alter table public.bestelregels add column if not exists lijst_kleur text;

insert into public.varianten (sku, product_id, formaat_id, papier_id, lijst, lijst_kleur, prijs,
                              prodigi_sku, prodigi_attributen, prodigi_status, prodigi_melding, prodigi_gecontroleerd_op, prodigi_product,
                              kosten, kostprijs, kosten_gecontroleerd_op)
select b.sku || '-HANGER-' || h.kleur_nl, b.product_id, b.formaat_id, b.papier_id, 'hanger', h.kleur, h.prijs,
       h.prodigi_sku, h.attributen, 'bevestigd', null, '2026-10-29T13:30:00Z', h.product,
       h.kosten, h.kostprijs, '2026-10-29T13:30:00Z'
  from public.varianten b
